{
  "title": "Meteor Escape",
  "description": "Pilot a spaceship through a starfield, dodging meteors and collecting power‑ups to survive as long as possible.",
  "controls": [
    "Arrow Left/Right to move horizontally",
    "Arrow Up to boost upward",
    "Arrow Down to descend"
  ]
}
